import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"DexGarmentLab: Dexterous Garment Manipulation Environment with Generalizable Policy","description":"","frontmatter":{"title":"DexGarmentLab: Dexterous Garment Manipulation Environment with Generalizable Policy","arxiv":"2505.11032","date":"2025-05-16","authors":"Yuran Wang, Ruihai Wu, Yue Chen, Jiarui Wang, Jiaqi Liang, Ziyu Zhu, Haoran Geng, Jitendra Malik, Pieter Abbeel, Hao Dong","categories":"cs.RO, cs.AI, cs.CV","topics":"灵巧手操作, 可变形物体, 仿真环境与数据生成","outline":[2,2]},"headers":[],"relativePath":"papers/2505.11032.md","filePath":"papers/2505.11032.md","lastUpdated":null}'),l={name:"papers/2505.11032.md"};function e(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="dexgarmentlab-dexterous-garment-manipulation-environment-with-generalizable-policy" tabindex="-1">DexGarmentLab: Dexterous Garment Manipulation Environment with Generalizable Policy <a class="header-anchor" href="#dexgarmentlab-dexterous-garment-manipulation-environment-with-generalizable-policy" aria-label="Permalink to &quot;DexGarmentLab: Dexterous Garment Manipulation Environment with Generalizable Policy&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2505.11032" target="_blank" rel="noreferrer">2505.11032</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-05-16</td></tr><tr><td><strong>作者</strong></td><td>Yuran Wang, Ruihai Wu, Yue Chen, Jiarui Wang, Jiaqi Liang, Ziyu Zhu, Haoran Geng, Jitendra Malik, Pieter Abbeel, Hao Dong</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用类别内衣物的稠密点对应把「一条专家演示」放大成整套自动采集的双灵巧手数据，再用「先靠对应定位抓取点、后靠扩散策略生成轨迹」的两段式策略跨形状泛化。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文基于 arXiv <strong>v3</strong>（2025-10-12 修订）撰写；NeurIPS 2025 Spotlight。v3 相比 v1 补充了 ACT / <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> / RDT / Eureka 四个新基线、遥操作数据对照与 sim-to-real 实验。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>衣物操作难在三件事叠在一起：类别多（上衣、裤子、裙子、帽子、手套……）、几何差异大、形变自由度近乎无穷。人类靠一双灵巧手可以毫不费力地折、抖、挂、穿，而机器人研究长期停留在双指夹爪 + 平铺衣物的设定。作者指出瓶颈不在算法而在基础设施：现有可变形仿真器（SoftGym 只支持上衣与裤子、FluidLab 只做流体）要么物体类型受限，要么用「隐形附着方块」把衣物粘在夹爪上来绕开接触力学——这在双指夹爪上勉强可用，换成灵巧手就会出现「一根手指碰一下就把整件衣服提起来」这种明显不合物理的行为。没有可信的灵巧手-衣物接触仿真，就没有数据；没有数据，就谈不上策略。解决它的价值很直接：家务机器人最高频的可变形物体就是衣物，而灵巧手正是让「捏起薄片、撑开袖口、边折边压」这类动作成为可能的硬件前提。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>SoftGym / PyBullet / FluidLab / Dexterous Gym 等环境各自覆盖了一小块：可微布料、刚体接触、流体、灵巧手，但没有一个同时支持「场景 + 衣物 + GPU 仿真 + 多种灵巧手 + 灵巧手衣物任务」。GarmentLab 引入 attach block 让衣物能被抓起，代价是接触力被旁路掉；论文的图 2 直接展示了后果——用灵巧手时衣物会以不自然的方式下垂。数据侧的问题更结构化：这些环境统统依赖遥操作或专门训练 RL 专家来采数据。遥操作在 60 维动作空间（每臂 6 自由度 + 每只 ShadowHand 24 自由度）下极其昂贵；RL 专家则要为每个任务手工设计奖励，而折叠、抖开这类长时程任务的奖励几乎无法写。算法侧，DP / DP3 这类模仿学习在刚体上表现好，但它们把「抓哪里」和「怎么走」耦合在一个端到端网络里；面对没见过的衣物形状，第一步抓错了后面全错。前人不是没考虑泛化，而是缺少一个能把「类别内不同实例的同一语义部位」对应起来的显式机制。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>已有的观察是：同一类别的衣物在结构上几乎同构——所有长袖上衣都有两只袖口、一个领口、一个下摆。UniGarmentManip 已经证明，用 Skeleton Merger 建立平铺衣物之间的骨架点对应、再用仿真中的点追踪把平铺态与形变态对应起来，可以训练出一个跨实例的稠密视觉对应模型。如果这个对应足够可靠，那么「专家在某件衣服上抓了哪个点」就可以自动迁移到任意新衣服上的同一语义点。这一步立刻把数据采集的成本结构改写了：不再是「每条轨迹一次遥操作」，而是「每个任务一次遥操作 + 无限次自动重放」。</p><p>顺着这条线往下推，会遇到第二个问题：光有抓取点不够。挂裤子时挂多高取决于裤长，折上衣时折到哪取决于衣宽——同一套「任务序列」在不同衣物上必须给出不同的轨迹。于是自然分成两段：定位交给对应模型（它对形状变化鲁棒），轨迹交给一个以衣物点云为条件的扩散策略（它可以按形状调整）。这个分工也解释了为什么单纯的 DP/DP3 会失败——它们没有第一段，抓取点本身就是从像素或点云里端到端猜出来的。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>同类衣物在结构上是同构的，所以「抓哪里」这件事可以完全靠跨实例的稠密对应转移，不需要学；真正需要学的只是「抓到之后按这件衣服的尺寸走多远、抬多高」。把这两件事拆开，泛化压力就从整条策略挪到了一个只需做点对点匹配的模型上；而端到端模仿学习之所以在新衣物上崩，正是因为它必须同时猜对这两件事。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Hang Coat 为例走一遍：</p><ul><li><strong>环境</strong>：基于 Isaac Sim 4.5.0，两台 UR10e + 两只 ShadowHand，动作空间 60 维；观测含关节位置、末端 6D 位姿、RGB 与裁剪降采样后的点云。大件衣物用 PBD 仿真，手套帽子这类弹性小件用 FEM。关键改动是引入粒子-刚体之间的 adhesion 与 friction、以及粒子间的 particle-adhesion/friction-scale，让灵巧手靠真实接触力抓起衣物，取代 attach block；后者还负责抑制粒子自碰撞导致的抖动。</li><li><strong>资产</strong>：ClothesNet 的 2500+ 件衣物、8 个类别，加上自建的衣架、挂钩、放置台、人体模型。</li><li><strong>一条专家演示</strong>：人工指定抓取点与任务序列，手部姿态用 LeapMotion 录制。</li><li><strong>GAM 推理</strong>：把 demo 点云 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span></span></span></span> 与新衣物点云 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7519em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span> 都归一化到规范空间（保证平移与尺度不变；旋转被当作形变状态，靠采样不同旋转来学），用预训练的 PointNet++ 提特征，取<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0489em;vertical-align:-0.247em;"></span><span class="mord"><span class="mord mathnormal">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8019em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.6304em;vertical-align:-0.8804em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.3557em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="mrel mtight">∈</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">O</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span></span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8804em;"><span></span></span></span></span></span><span class="mspace"> </span><span class="mopen">⟨</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">p</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3448em;"><span style="top:-2.3488em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1512em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">⟩</span></span></span></span></span></p> 得到新衣物上的对应抓取点。</li><li><strong>自动执行与录制</strong>：IK 控制手臂按任务序列走，PD 控制器按 demo 手姿驱动灵巧手；轨迹按衣物尺寸自适应（挂高、前伸距离随衣长变）。全过程录像与状态入库。每任务采 100 条，单条 30–80 秒。</li><li><strong>HALO 部署</strong>：第一阶段 GAM 给出左右手目标点并移动过去；第二阶段 SADP——把衣物点云与左右目标点的 affordance 拼接后过 PointNet++ 得 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span><span class="mord mathnormal mtight">a</span><span class="mord mathnormal mtight" style="margin-right:0.0278em;">r</span><span class="mord mathnormal mtight">m</span><span class="mord mathnormal mtight">e</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，交互物体点云过 MLP 得 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">bj</span><span class="mord mathnormal mtight">ec</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>，两者拼成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">sce</span><span class="mord mathnormal mtight">n</span><span class="mord mathnormal mtight">e</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，再与整体环境点云和机器人状态融合成扩散条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span></span></span></span>，去噪生成 60 维关节动作。无交互物体的自交互任务用 SADP_G 变体，省掉 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">F</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">o</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">bj</span><span class="mord mathnormal mtight">ec</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>。</li></ul><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>GAM 的训练目标是 InfoNCE。设 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span><span class="mclose">)</span></span></span></span> 是一对正对应点（同一语义部位在两件衣物或两种形变下的实例），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mclose">)</span></span></span></span> 是 PointNet++ 特征：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">InfoNCE</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.4632em;vertical-align:-1.0362em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">exp</span><span class="mopen">(⟨</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">⟩</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.0017em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">n</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">exp</span><span class="mopen">(⟨</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3419em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.7027em;"><span style="top:-2.214em;margin-left:-0.0359em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">n</span></span></span><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mbin mtight">−</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.286em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.3502em;"><span></span></span></span></span></span></span><span class="mclose">⟩</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mop">exp</span><span class="mopen">(⟨</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">p</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mclose">⟩</span><span class="mord">/</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.0362em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>直觉上它在做一件很朴素的事：把「袖口」的特征拉到所有袖口那里去，把它从领口、下摆推开。每个正对配 150 个负对，一个 batch 是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">32</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">32</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">20</span></span></span></span> 组点对。之所以这个损失足以支撑整套系统，是因为推理时用的只有内积排序（上面的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">max</span></span></span></span>），而 InfoNCE 恰好是直接优化这个排序的对比目标——训练目标与推理用法完全一致，中间没有额外的对齐假设。</p><p>两处不变性的处理方式不同，值得注意：平移与尺度靠输入端归一化到规范空间<strong>显式</strong>保证；旋转则<strong>不</strong>做显式处理，而是被当成「衣物的一种形变状态」，靠在训练集里生成足够多的旋转样本来隐式覆盖。这意味着旋转不变性只是统计上的、没有结构保证。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：自动采集的数据够好吗？</strong> 附录表 5 显示 14 个仿真任务的采集成功率在 82.0%–99.0%（最低是 Fold Tops，最高是 Hang Trousers），单条 36 秒到 1 分 42 秒。表 6 用三个代表任务把自动数据与遥操作数据训出的 HALO 对比：Hang Tops 0.92 vs 0.88、Wear Bowlhat 0.72 vs 0.70、真机 Fold Tops 13/15 vs 13/15。结论应当如实表述为——<strong>自动数据与遥操作数据训出的策略基本等价，优势在成本而非质量</strong>。</p><p><strong>问题二：两段式设计有没有用？</strong> 表 2 覆盖 14 个任务，每任务 50 episode × 3 seed。DP 在 0.41–0.67，DP3 在 0.47–0.63，HALO 在 0.72–0.92。两个消融都明显下滑：去掉 GAM（只留 SADP）0.61–0.75，去掉 SADP（GAM + DP3）0.53–0.71。图 7 给出机理性证据：无 GAM 时抓不到正确部位，无 SADP 时轨迹不随衣长/挂钩位置调整。</p><p><strong>问题三：能不能打过更强的基线？</strong> 附录表 7 加了四个：ACT 最弱（0.35–0.51），<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 RDT 明显好于从零训的 IL（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在 Hang Coat 上 0.72、Fling Dress 0.69），Eureka（RL+VLM）在 Hang Coat 与 Wear Bowlhat 上只有 0.16 / 0.08，长时程的 Fling / Fold 完全跑不出结果——作者归因于 Isaac Sim 缺并行支持与长时程奖励难写。</p><p><strong>问题四：能不能迁到真机？</strong> 路线一（真机直接自动采数据 + 训练）用 RealMan RM75-6F + Psibot G0-R + D435，四个任务各 15 次：HALO 13/13/11/14，DP 9/10/6/10，DP3 8/8/7/9。路线二（仿真训练 + 迁移）用 UR10e + ShadowHand + Kinect，只训仿真数据时 Hang Trousers 8/15、Wear Hat 9/15；各加 15 条真机数据后都升到 13/15。</p><p>需要如实指出：正文与摘要多处称 15 个任务，实际策略评测只有 14 个——附录 K.15 明确说明 Wear Glove 因为需要食指精确插入、当前 FEM 与灵巧手仿真做不到，改用了 attach block、没有初始位置随机化、也<strong>没有做策略评测</strong>。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：DexGarmentLab 用 adhesion/friction/particle-scale 参数替代 attach block，让灵巧手靠真实接触力抓衣物，是第一个面向双灵巧手衣物操作的环境（Isaac Sim，2500+ 件衣物 / 8 类 / 15 个任务场景）。它用类别内稠密对应（GAM，基于 UniGarmentManip）把一条专家演示放大成全自动的数据采集流水线，14 个任务的采集成功率 82%–99%。HALO 把策略拆成「GAM 定位 + 结构感知扩散策略生成轨迹」两段，仿真上 0.72–0.92，全面高于 DP（0.41–0.67）、DP3（0.47–0.63）与两个消融。真机四任务上 11/15–14/15，且自动数据与遥操作数据训出的策略基本等价。仿真到真机的策略迁移仍有明显 gap（8/15、9/15），加 15 条真机数据即可补到 13/15。</p><p><strong>3 句话版</strong>：同类衣物结构同构，因此「抓哪里」可以靠跨实例稠密对应免费获得，只有「怎么走」需要学。据此把数据采集从遥操作降级为「一条演示 + 自动重放」，把策略拆成定位与轨迹两段。两处改动都被消融支持，但成功判据偏宽（基线已有 0.5 左右）。</p><p><strong>1 句话版</strong>：把衣物操作里的泛化压力从策略挪到一个只做点对点匹配的对应模型上。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>类别内的稠密结构对应在任意形变与遮挡下依然稳定可匹配</strong>。它是整栋楼的地基——数据采集靠它把 demo 点搬到新衣物上，策略的第一阶段又靠它定位，两处失效会同时发生且不可分离。作者在附录 I.3 自己承认：遮挡或强形变区域上 GAM 不总能预测准，非对称设计（单袖上衣）或装饰繁复的服装会扭曲点云，同时拖垮 GAM 与 SADP，建议的缓解是「先做一次抖开动作把关键区域暴露出来」——但这本身又依赖 GAM 找到可抖的点。</p><p>一个更隐蔽的风险是评测的循环性：附录 K.1.3 说明 Fold Tops 的成功判据是<strong>先用 GAM 定位袖口、领口、下摆四个关键点</strong>，由它们围出一个矩形区域，再看折后衣物是否有 85% 的面积落在区域内。也就是说，被评的方法与定义评分区域的模块是同一个。作者做了两点缓解——区域是在<strong>初始平铺态</strong>上算的（GAM 在平铺态最可靠），且每条 episode 都保留末态图与完整视频供人工复核（附录 K.16）。但这条循环链没有被定量拆除，例如没有给出「用人工标注关键点定义区域」时各方法分数的变化。另一类判据则明显偏宽：Hang Coat 的成功条件仅仅是衣物中心的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.044em;">z</span></span></span></span> 坐标落在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">2.0</span><span class="mclose">)</span></span></span></span> 区间内（排除掉地上与仿真异常），并不检查是否真的挂在了挂钩上。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可做、且不需要复现整套系统的判决实验：只取 Fold Tops 与 Hang Coat 两个任务，实现一个<strong>盲脚本基线</strong>——完全不看点云，把 100 条自动采集轨迹在关节空间取平均得到一条固定轨迹，在同样的随机化范围内回放 50 次 × 3 seed。测量它在论文自带判据下的成功率。判据：若盲脚本能拿到 0.4 以上（即接近 DP/DP3 的水平），则表 2 中 0.5 与 0.9 之间的差距主要反映的是「能否稳定完成粗动作」，而非泛化能力，此时应当把成功判据收紧（例如 Hang 类要求接触检测到挂钩）后重跑；若盲脚本只有 0.1 上下，则现有判据是有区分度的，DP/DP3 的 0.5 确实来自学习。这个实验只需要环境本体与已发布的数据，不涉及任何模型训练。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>反对者的最强攻击是<strong>增益归因不可拆</strong>。表 2 有四个配置：DP3（既无 GAM 也无 SADP，0.47–0.63）、w/o GAM（只有 SADP，0.61–0.75）、w/o SADP（GAM + DP3，0.53–0.71）、HALO（0.72–0.92）。以 Hang Tops 为例：0.53 → 单加 SADP 0.64 → 单加 GAM 0.70 → 全加 0.92。两个单项各贡献约 0.11 和 0.17，但合起来贡献 0.39——存在一个约 0.11 的超加性项，论文没有讨论。这个交互项可以有一个完全不同的解释：SADP 的输入里显式拼接了「左右目标点 affordance」作为绑定特征，所以 w/o GAM 的那一行实际上是<strong>把 SADP 的一路输入喂了噪声</strong>，而不是「去掉 GAM」的干净对照。真正的对照应当是「GAM 定位 + 不带 affordance 通道的 DP3」与「随机采样点定位 + 完整 SADP」。</p><p>另一条攻击针对仿真本身：附录 I.1 承认 PBD 的粒子间连接松散、易穿透且会持续抖动，FEM 则倾向恢复原形。整套「灵巧手靠真实摩擦与粘附抓起衣物」的叙事，其可信度上界由这两个求解器决定，而论文没有任何真实布料的力学参数标定实验。可预测的失败场景：需要维持持续张力的任务（撑开袖口穿进去、拉直褶皱），PBD 的松散粒子会让张力无法传递——这恰好是唯一一个被放弃评测的任务 Wear Glove 所在的类别。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动的局限</strong>：GAM 的 affordance 语义是「与专家演示中的那个点对应」，因此系统能力的上界被那一条演示锁死。演示里没抓过的部位，永远不会被考虑；专家选了一个次优抓点，全部 100 条数据都会次优。</p><p><strong>新的 framing</strong>：把 affordance 从「与 demo 对应」重新定义为「可达构型集的张成能力」。给定当前衣物构型 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 与目标构型集合 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span></span></span></span>，把抓取点 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">p</span></span></span></span> 的价值定义为在双手约束下从 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 出发可到达的目标子集的测度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">μ</span><span class="mopen">(</span><span class="mord mathcal">R</span><span class="mopen">(</span><span class="mord mathnormal">p</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∩</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mclose">)</span></span></span></span>，用可微布料仿真反传来估这个量。这样 affordance 变成任务无关、演示无关的物理量，一次学好可服务所有任务，也自然给出「先抖开再折」这类两步策略的理由（第一步的价值就是把可达集撑大）。</p><p><strong>可借鉴的相邻领域</strong>：刚体操作里成熟的 manipulability ellipsoid 与 grasp wrench space——它们正是把「这个抓法能做多少事」形式化成一个几何测度；以及可微仿真（DiffCloth / $\\nabla$Sim）提供的梯度通道。</p><p><strong>第一个实验</strong>：在 Fold Tops 与 Fling Tops 上，对同一件衣物枚举 GAM 给出的点与可达集最大点，各采 100 条数据分别训 SADP，比较在形状分布外实例（非对称、单袖、装饰繁复——即论文 I.3 自认失败的那一类）上的成功率。若可达集点显著更好，说明「对应」只是「可操作性」的一个廉价代理，而在分布边缘会失效。</p>',44)])])}const d=a(l,[["render",e]]);export{o as __pageData,d as default};
